 protected override void OnPaint(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;var r=new Rectangle(0,0,Width-1,Height-1);using(var p=new GraphicsPath()){int d=18;p.AddArc(r.Left,r.Top,d,d,180,90);p.AddArc(r.Right-d,r.Top,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.Left,r.Bottom-d,d,d,90,90);p.CloseFigure();using(var b=new SolidBrush(!Enabled?Color.FromArgb(42,47,56):Primary?Color.FromArgb(0,153,239):Color.FromArgb(45,51,63)))e.Graphics.FillPath(b,p);}TextRenderer.DrawText(e.Graphics,Text,Font,r,Enabled?Color.White:Color.Gray,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}
}
sealed class Setup : Form {
