 readonly string root=AppDomain.CurrentDomain.BaseDirectory;
 Dictionary<string,object>[] devices=new Dictionary<string,object>[0];int page=0;bool loaded=false,finished=false;static bool rendering=false;
 static readonly Color Muted=Color.FromArgb(157,170,189),Blue=Color.FromArgb(70,190,255);
 static string Q(string s){if(s.Contains("\"")||s.Contains("\n")||s.Contains("\r"))throw new ArgumentException("Invalid path");return "\""+s+"\"";}
 Setup(){Text="GlideMouse Setup";ClientSize=new Size(660,580);AutoScaleMode=AutoScaleMode.Dpi;BackColor=Color.FromArgb(19,23,30);ForeColor=Color.FromArgb(240,245,252);Font=new Font("Segoe UI",10);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;
 Controls.Add(new Label{Text="GLIDEMOUSE",ForeColor=Blue,Font=new Font("Segoe UI",10,FontStyle.Bold),Location=new Point(30,24),Size=new Size(240,25)});
 progress.Location=new Point(370,24);progress.Size=new Size(260,25);progress.TextAlign=ContentAlignment.MiddleRight;progress.ForeColor=Muted;Controls.Add(progress);
 title.Location=new Point(30,66);title.Size=new Size(600,49);title.Font=new Font("Segoe UI",25,FontStyle.Bold);Controls.Add(title);body.Location=new Point(30,131);body.Size=new Size(600,360);Controls.Add(body);
 back.Location=new Point(30,512);back.Size=new Size(104,42);back.Text="Back";back.Click+=(s,e)=>{page--;Render();};Controls.Add(back);
 next.Location=new Point(430,512);next.Size=new Size(200,42);next.Click+=async(s,e)=>{if(finished){Close();return;}if(page<2){page++;Render();}else await Install();};Controls.Add(next);
 mice.DropDownStyle=ComboBoxStyle.DropDownList;mice.FlatStyle=FlatStyle.Flat;mice.BackColor=Color.FromArgb(38,45,57);mice.ForeColor=ForeColor;mice.SelectedIndexChanged+=(s,e)=>EnableNext();
 apple.BackColor=Color.FromArgb(38,45,57);apple.ForeColor=ForeColor;apple.BorderStyle=BorderStyle.FixedSingle;consent.ForeColor=Muted;consent.CheckedChanged+=(s,e)=>EnableNext();status.ForeColor=Muted;status.Size=new Size(596,64);
 Shown+=async(s,e)=>{if(!rendering)await Discover();};Render();}
 void Copy(string text,int y,int h=45,bool bold=false){body.Controls.Add(new Label{Text=text,Location=new Point(0,y),Size=new Size(596,h),ForeColor=bold?ForeColor:Muted,Font=new Font("Segoe UI",bold?13:10,bold?FontStyle.Bold:FontStyle.Regular)});}
 void Render(){body.Controls.Clear();progress.Text=finished?"READY TO GLIDE":"SETUP / "+(page+1)+" OF 3";back.Visible=page>0&&!finished;back.Enabled=true;
 if(finished){title.Text="You're all set.";Copy("Save your work, then restart Windows.",10,44,true);Copy("After sign-in, click the mouse outline in the Windows notification area. A compatible Windhawk Island can use the same controls.",76,70);Copy("Mechanical clicks remain the default. Momentum, desktop swipes and double-tap gestures run in the background.",170,65);Copy("Tap to click is optional and starts off.\nEnable it in the widget whenever you want.",261,60);next.Text="Finish";next.Enabled=true;return;}
 if(page==0){title.Text="A smoother kind of mouse.";Copy("Your Magic Mouse. Now at home on Windows.",5,42,true);Copy("01   SCROLL WITH MOMENTUM\n       Flick, let go, and touch again to stop.",70,62);Copy("02   MOVE BETWEEN DESKTOPS\n       Two-finger swipes and familiar tap gestures.",149,62);Copy("03   ONE CLICK TO YOUR CONTROLS\n       Connection, battery and settings in your taskbar.",228,62);Copy("Windows 11 x64 \u00b7 USB-C Magic Mouse \u00b7 Early preview",321,28);next.Text="Get started";}
 else if(page==1){title.Text="Meet your Magic Mouse.";Copy("Pair and connect your mouse in Windows first.",0,35);mice.Location=new Point(0,44);mice.Size=new Size(596,32);body.Controls.Add(mice);Copy("Original Apple driver package",100,29,true);Copy("Choose AppleWirelessMouse.inf, with its original .cat and .sys files beside it. If the complete original package is installed, leave this blank.",138,50);apple.Location=new Point(0,196);apple.Size=new Size(466,30);body.Controls.Add(apple);var browse=new ModernButton{Text="Choose file",Location=new Point(480,191),Size=new Size(116,39)};browse.Click+=(s,e)=>{using(var d=new OpenFileDialog{Filter="Apple mouse package|AppleWirelessMouse.inf"})if(d.ShowDialog()==DialogResult.OK)apple.Text=d.FileName;};body.Controls.Add(browse);var link=new LinkLabel{Text="Driver requirements and installation guide \u2197",Location=new Point(0,245),Size=new Size(596,28),LinkColor=Blue};link.LinkClicked+=(s,e)=>Process.Start("https://github.com/WendelinProfiler/GlideMouse#requirements");body.Controls.Add(link);status.Location=new Point(0,293);body.Controls.Add(status);next.Text="Continue";}
 else{title.Text="Ready when you are.";Copy("What will be installed",0,34,true);Copy("\u2022 GlideMouse controls in your Windows notification area\n\u2022 A background gesture component at sign-in\n\u2022 A signed USB filter on the selected Bluetooth root hub\n\u2022 An automatic bridge restricted to your mouse reports",48,108);Copy("Your data stays on this PC. No packet files, screen capture or telemetry. Other Bluetooth traffic is discarded in memory.",174,58);consent.Text="Install these components with administrator rights.\nI understand that Windows needs a restart.";consent.Location=new Point(0,251);consent.Size=new Size(596,56);body.Controls.Add(consent);Copy("Test mode, Secure Boot and memory integrity are not changed.",322,30);next.Text="Install GlideMouse";}EnableNext();}
 void EnableNext(){next.Enabled=page==0||(page==1&&loaded&&mice.SelectedIndex>=0)||(page==2&&consent.Checked);}
 async Task Discover(){try{string json=await Task.Run(()=>RunPlan());devices=new JavaScriptSerializer().Deserialize<Dictionary<string,object>[]>(json);foreach(var d in devices)mice.Items.Add((string)d["Name"]+"  \u00b7  "+(string)d["Address"]);if(mice.Items.Count>0){mice.SelectedIndex=0;status.Text="Mouse found. Administrator permission is requested only when installing.";}else status.Text="No supported connected mouse found. Pair your USB-C mouse and reopen Setup. This preview requires a USB Bluetooth adapter directly under a root hub.";loaded=true;EnableNext();}catch(Exception ex){status.Text="Could not detect the mouse: "+ex.Message;}}
 string RunPlan(){var info=new ProcessStartInfo("powershell.exe","-NoProfile -ExecutionPolicy Bypass -File "+Q(Path.Combine(root,"installer","Install.ps1"))+" -Plan"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var p=Process.Start(info)){var errors=p.StandardError.ReadToEndAsync();string result=p.StandardOutput.ReadToEnd();p.WaitForExit();if(p.ExitCode!=0)throw new Exception(errors.Result);return result;}}
 async Task Install(){next.Enabled=false;back.Enabled=false;try{string args="-NoProfile -ExecutionPolicy Bypass -File "+Q(Path.Combine(root,"installer","Invoke-Install.ps1"))+" -MouseAddress "+Q((string)devices[mice.SelectedIndex]["Address"])+" -UserSid "+Q(WindowsIdentity.GetCurrent().User.Value)+" -UserHome "+Q(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile));if(!String.IsNullOrWhiteSpace(apple.Text))args+=" -AppleDriver "+Q(apple.Text);title.Text="Getting things ready\u2026";next.Text="Installing\u2026";var info=new ProcessStartInfo("powershell.exe",args){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden};int code=await Task.Run(()=>{using(var p=Process.Start(info)){p.WaitForExit();return p.ExitCode;}});if(code!=0){string result=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"GlideMouse","setup-result.txt");throw new Exception(File.Exists(result)?File.ReadAllText(result):"Installation did not complete. See the installation guide for recovery.");}finished=true;Render();}catch(Exception ex){Render();MessageBox.Show(this,ex.Message,"GlideMouse Setup",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
 [STAThread]static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);rendering=args.Length>=2&&args[0]=="--render-preview";using(var form=new Setup()){if(rendering){if(args.Length>2){int previewPage;int.TryParse(args[2],out previewPage);form.page=Math.Max(0,Math.Min(2,previewPage));form.Render();}form.AutoScaleDimensions=new SizeF(96,96);form.PerformAutoScale();form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-30000,-30000);form.Show();Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,form.Size));image.Save(args[1]);}form.Hide();return;}form.AutoScaleDimensions=new SizeF(96,96);form.PerformAutoScale();Application.Run(form);}}
